import json
# Reconstruct the regular 30x30 test grid as shown: 4x4 tiles at rows/cols 1,8,15,22,
# 5x5 each, with 2-cell gutters and the final partial border column/row.
A=[[0]*30 for _ in range(30)]
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate([1,8,15,22]):
  for tj,c0 in enumerate([1,8,15,22]):
    color=vals[ti][tj]
    for r in range(r0,r0+5):
      for c in range(c0,c0+5):
        A[r][c]=color if 1<=r-r0<=3 and 1<=c-c0<=3 else 4
# final partial stripe at right/bottom, matching displayed grid
for r0 in [1,8,15,22]:
  for r in range(r0,r0+5): A[r][29]=4
for c0 in [1,8,15,22]:
  for c in range(c0,c0+5): A[29][c]=4
# Fill only gutter cells between repeated non-dominant center markers, across each row/column.
centers=[3,10,17,24]
for r in centers:
  for color in (3,8):
    inds=[j for j,c in enumerate(centers) if A[r][c]==color]
    if len(inds)>1:
      for left,right in zip(inds,inds[1:]):
        for j in range(centers[left]+1,centers[right]):
          if A[r][j]==0: A[r][j]=color
for c in centers:
  for color in (3,8):
    inds=[i for i,r in enumerate(centers) if A[r][c]==color]
    if len(inds)>1:
      for top,bottom in zip(inds,inds[1:]):
        for i in range(centers[top]+1,centers[bottom]):
          if A[i][c]==0: A[i][c]=color
assert len(A)==30 and all(len(row)==30 for row in A)
print(json.dumps({'action':'submit','grid':A},separators=(',',':')))

